export const listSecureNotes = async (
  params?: ListSecureNotesParams,
  options?: RequestInit,
  fetchFn?: typeof globalThis.fetch,
): Promise<listSecureNotesResponse> => {
  const res = await (fetchFn ?? fetch)(getListSecureNotesUrl(params), {
    ...options,
    method: "GET",
  });
  const data: listSecureNotesResponse["data"] = (await decodeResponse(
    res,
    { "200": "json", default: "json" },
    {},
  )) as listSecureNotesResponse["data"];
  return { data, status: res.status, headers: res.headers } as listSecureNotesResponse;
};

