/**
 * @summary Create a secure note secret
 */
export const createSecureNote = async (
  createSecureNoteRequest: CreateSecureNoteRequest,
  options?: RequestInit,
  fetchFn?: typeof globalThis.fetch,
): Promise<createSecureNoteResponse> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  const res = await (fetchFn ?? fetch)(getCreateSecureNoteUrl(), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...getHeaders(options?.headers) },
    body: JSON.stringify(createSecureNoteRequest),
  });
  const data: createSecureNoteResponse["data"] = (await decodeResponse(
    res,
    { "201": "json", default: "json" },
    {},
  )) as createSecureNoteResponse["data"];
  return { data, status: res.status, headers: res.headers } as createSecureNoteResponse;
};

